// C-03a test lab: a throwaway PKI generated by `openssl` at test time in a temp dir (nothing committed; deleted at the
// end) and raw loopback servers that count every byte they receive, so "zero bytes of the request" is measured on the
// server side, not inferred from the client.
import 'dart:async';
import 'dart:convert';
import 'dart:io';
import 'dart:typed_data';

/// One leaf key and certificate of the lab PKI.
class LabLeaf {
  final String name;
  final String certPath;
  final String keyPath;
  final Uint8List der;

  /// `sha256/<base64>` computed by openssl from the private key (pkey -pubout -outform DER | dgst -sha256).
  final String opensslPin;
  LabLeaf(this.name, this.certPath, this.keyPath, this.der, this.opensslPin);

  SecurityContext serverContext() => SecurityContext()
    ..useCertificateChain(certPath)
    ..usePrivateKey(keyPath);
}

class LabPki {
  final Directory dir;
  final String caPath;
  final Map<String, LabLeaf> leaves;
  LabPki._(this.dir, this.caPath, this.leaves);

  LabLeaf operator [](String name) => leaves[name]!;

  /// Trusts only the lab CA (not the system roots), like a device whose only anchor is the issuer of these leaves.
  SecurityContext clientContext() => SecurityContext(withTrustedRoots: false)..setTrustedCertificates(caPath);

  Future<void> dispose() => dir.delete(recursive: true);

  static const _sans = 'DNS:lab-pin.test,DNS:api.lab-pin.test,DNS:other.test';

  /// Leaves: `a` RSA 2048 and `b` EC P-256 (the pinned and the backup key), `x` EC P-384 (valid chain, key not
  /// pinned), `wrong` (EC P-256, valid chain for `wrong.test` only) and `self` (self-signed, not issued by the CA).
  static Future<LabPki> create() async {
    final dir = await Directory.systemTemp.createTemp('sentomaru-c03a-');
    const rsa = '-algorithm RSA -pkeyopt rsa_keygen_bits:2048';
    const p256 = '-algorithm EC -pkeyopt ec_paramgen_curve:P-256';
    const p384 = '-algorithm EC -pkeyopt ec_paramgen_curve:P-384';
    final script = '''
set -euo pipefail
cd "${dir.path}"
openssl genpkey $p256 -out ca.key 2>/dev/null
openssl req -x509 -new -key ca.key -subj /CN=sentomaru-c03a-test-ca -days 2 -out ca.pem \\
  -addext basicConstraints=critical,CA:TRUE -addext keyUsage=critical,keyCertSign,cRLSign 2>/dev/null
leaf() { # name, genpkey args, SANs, self-signed?
  openssl genpkey \$2 -out "\$1.key" 2>/dev/null
  printf 'subjectAltName=%s\\nbasicConstraints=CA:FALSE\\nextendedKeyUsage=serverAuth\\n' "\$3" > "\$1.ext"
  openssl req -new -key "\$1.key" -subj "/CN=\$1" -out "\$1.csr" 2>/dev/null
  if [ "\$4" = self ]; then
    openssl x509 -req -in "\$1.csr" -signkey "\$1.key" -days 2 -extfile "\$1.ext" -out "\$1.pem" 2>/dev/null
  else
    openssl x509 -req -in "\$1.csr" -CA ca.pem -CAkey ca.key -set_serial "0x\$(openssl rand -hex 8)" -days 2 \\
      -extfile "\$1.ext" -out "\$1.pem" 2>/dev/null
  fi
  openssl x509 -in "\$1.pem" -outform DER -out "\$1.der"
  openssl pkey -in "\$1.key" -pubout -outform DER | openssl dgst -sha256 -binary | openssl base64 -A > "\$1.pin"
}
leaf a "$rsa" "$_sans" ca
leaf b "$p256" "$_sans" ca
leaf x "$p384" "$_sans" ca
leaf wrong "$p256" "DNS:wrong.test" ca
leaf self "$p256" "$_sans" self
''';
    final result = await Process.run('bash', ['-c', script]);
    if (result.exitCode != 0) {
      throw StateError('openssl lab PKI failed (openssl is required by these tests): ${result.stderr}');
    }
    final leaves = <String, LabLeaf>{};
    for (final n in ['a', 'b', 'x', 'wrong', 'self']) {
      final pin = (await File('${dir.path}/$n.pin').readAsString()).trim();
      leaves[n] = LabLeaf(n, '${dir.path}/$n.pem', '${dir.path}/$n.key',
          await File('${dir.path}/$n.der').readAsBytes(), 'sha256/$pin');
    }
    return LabPki._(dir, '${dir.path}/ca.pem', leaves);
  }
}

/// A loopback server (TLS or plain) that counts accepted connections and every byte received on them, and answers
/// each complete HTTP request with [response] (a raw HTTP/1.1 head; `Connection: close`).
class CountingServer {
  final Stream<Socket> _accepted;
  final Future<void> Function() _close;
  final int port;
  int connections = 0;
  int closed = 0;
  int bytes = 0;

  /// Keep the connection open after an answer (keep-alive) instead of closing it.
  bool keepAlive = false;
  final StringBuffer text = StringBuffer();
  String response = 'HTTP/1.1 200 OK\r\nContent-Length: 2\r\nContent-Type: text/plain\r\nConnection: close\r\n\r\nok';

  CountingServer._(this._accepted, this._close, this.port) {
    _accepted.listen(_serve, onError: (_) {});
  }

  /// TLS server: a socket is counted only after its handshake completed on the server side.
  static Future<CountingServer> tls(SecurityContext context) async {
    final s = await SecureServerSocket.bind(InternetAddress.loopbackIPv4, 0, context);
    return CountingServer._(s, () => s.close(), s.port);
  }

  static Future<CountingServer> plain() async {
    final s = await ServerSocket.bind(InternetAddress.loopbackIPv4, 0);
    return CountingServer._(s, () => s.close(), s.port);
  }

  void _serve(Socket socket) {
    connections++;
    final buffer = BytesBuilder();
    var answered = false;
    socket.listen((data) {
      bytes += data.length;
      buffer.add(data);
      final seen = latin1.decode(buffer.toBytes());
      text.write(latin1.decode(data));
      final end = seen.indexOf('\r\n\r\n');
      if (answered || end < 0) return;
      if (seen.startsWith('CONNECT ')) {
        // A proxy that refuses every tunnel: enough to see what the client asked for.
        answered = true;
        socket.add(latin1.encode('HTTP/1.1 502 Bad Gateway\r\nContent-Length: 0\r\nConnection: close\r\n\r\n'));
        socket.close().catchError((_) {});
        return;
      }
      final length = RegExp(r'content-length:\s*(\d+)', caseSensitive: false).firstMatch(seen.substring(0, end));
      if (length != null && seen.length - end - 4 < int.parse(length.group(1)!)) return;
      if (keepAlive) {
        socket.add(latin1.encode(response.replaceFirst('Connection: close', 'Connection: keep-alive')));
        buffer.clear();
        return;
      }
      answered = true;
      socket.add(latin1.encode(response));
      socket.close().catchError((_) {});
    }, onError: (_) => closed++, onDone: () => closed++, cancelOnError: true);
  }

  Future<void> close() => _close();
}

/// The TCP seam of the connection factory: every DNS name goes to loopback on the URL's port.
Future<ConnectionTask<Socket>> loopbackConnector(String host, int port) =>
    Socket.startConnect(InternetAddress.loopbackIPv4, port);

/// The TLS seam: TCP to loopback, then the handshake with the NAME (SNI and host name check still use it). Unlike the
/// production `SecureSocket.startConnect`, a cancel here stops only the TCP part (the timeout test uses production).
Future<ConnectionTask<SecureSocket>> loopbackTlsConnector(
    String host, int port, SecurityContext? context, bool Function(X509Certificate)? onBadCertificate) async {
  final tcp = await Socket.startConnect(InternetAddress.loopbackIPv4, port);
  Future<SecureSocket> secure() async =>
      SecureSocket.secure(await tcp.socket, host: host, context: context, onBadCertificate: onBadCertificate);
  return ConnectionTask.fromSocket(secure(), tcp.cancel);
}

/// Waits until [condition] holds or [timeout] passes (server-side counters update asynchronously).
Future<void> eventually(bool Function() condition, {Duration timeout = const Duration(seconds: 2)}) async {
  final deadline = DateTime.now().add(timeout);
  while (!condition() && DateTime.now().isBefore(deadline)) {
    await Future<void>.delayed(const Duration(milliseconds: 10));
  }
}
